alter table run_jobs add column if not exists lock_token uuid;create unique index if not exists provider_runs_job_unique on provider_runs ((metadata->>'job_id')) where metadata ? 'job_id';create index if not exists usage_events_user_type_created_idx on usage_events(user_id,event_type,created_at desc);create table if not exists checker_rate_limits(id uuid primary key default gen_random_uuid(),key_hash text not null,window_start timestamptz not null,count integer not null default 1,created_at timestamptz not null default now(),unique(key_hash,window_start));